function createBaseAgentMetrics(): AgentMetrics {
  return { inputTokens: 0, outputTokens: 0, reasoningTokens: 0, costUsd: 0, toolCalls: 0, filesTouched: [] };
}

export const AgentMetrics: MessageFns<AgentMetrics> = {
  encode(message: AgentMetrics, writer: BinaryWriter = new BinaryWriter()): BinaryWriter {
    if (message.inputTokens !== 0) {
      writer.uint32(8).uint64(message.inputTokens);
    }
    if (message.outputTokens !== 0) {
      writer.uint32(16).uint64(message.outputTokens);
    }
    if (message.reasoningTokens !== 0) {
      writer.uint32(24).uint64(message.reasoningTokens);
    }
    if (message.costUsd !== 0) {
      writer.uint32(33).double(message.costUsd);
    }
    if (message.toolCalls !== 0) {
      writer.uint32(40).uint64(message.toolCalls);
    }
    for (const v of message.filesTouched) {
      writer.uint32(50).string(v!);
    }
    return writer;
  },

  decode(input: BinaryReader | Uint8Array, length?: number): AgentMetrics {
    const reader = input instanceof BinaryReader ? input : new BinaryReader(input);
    const end = length === undefined ? reader.len : reader.pos + length;
    const message = createBaseAgentMetrics();
    while (reader.pos < end) {
      const tag = reader.uint32();
      switch (tag >>> 3) {
        case 1: {
          if (tag !== 8) {
            break;
          }

          message.inputTokens = longToNumber(reader.uint64());
          continue;
        }
        case 2: {
          if (tag !== 16) {
            break;
          }

          message.outputTokens = longToNumber(reader.uint64());
          continue;
        }
        case 3: {
          if (tag !== 24) {
            break;
          }

          message.reasoningTokens = longToNumber(reader.uint64());
          continue;
        }
        case 4: {
          if (tag !== 33) {
            break;
          }

          message.costUsd = reader.double();
          continue;
        }
        case 5: {
          if (tag !== 40) {
            break;
          }

          message.toolCalls = longToNumber(reader.uint64());
          continue;
        }
        case 6: {
          if (tag !== 50) {
            break;
          }

          message.filesTouched.push(reader.string());
          continue;
        }
      }
      if ((tag & 7) === 4 || tag === 0) {
        break;
      }
      reader.skip(tag & 7);
    }
    return message;
  },

  fromJSON(object: any): AgentMetrics {
    return {
      inputTokens: isSet(object.inputTokens)
        ? globalThis.Number(object.inputTokens)
        : isSet(object.input_tokens)
        ? globalThis.Number(object.input_tokens)
        : 0,
      outputTokens: isSet(object.outputTokens)
        ? globalThis.Number(object.outputTokens)
        : isSet(object.output_tokens)
        ? globalThis.Number(object.output_tokens)
        : 0,
      reasoningTokens: isSet(object.reasoningTokens)
        ? globalThis.Number(object.reasoningTokens)
        : isSet(object.reasoning_tokens)
        ? globalThis.Number(object.reasoning_tokens)
        : 0,
      costUsd: isSet(object.costUsd)
        ? globalThis.Number(object.costUsd)
        : isSet(object.cost_usd)
        ? globalThis.Number(object.cost_usd)
        : 0,
      toolCalls: isSet(object.toolCalls)
        ? globalThis.Number(object.toolCalls)
        : isSet(object.tool_calls)
        ? globalThis.Number(object.tool_calls)
        : 0,
      filesTouched: globalThis.Array.isArray(object?.filesTouched)
        ? object.filesTouched.map((e: any) => globalThis.String(e))
        : globalThis.Array.isArray(object?.files_touched)
        ? object.files_touched.map((e: any) => globalThis.String(e))
        : [],
    };
  },

  toJSON(message: AgentMetrics): unknown {
    const obj: any = {};
    if (message.inputTokens !== 0) {
      obj.inputTokens = Math.round(message.inputTokens);
    }
    if (message.outputTokens !== 0) {
      obj.outputTokens = Math.round(message.outputTokens);
    }
    if (message.reasoningTokens !== 0) {
      obj.reasoningTokens = Math.round(message.reasoningTokens);
    }
    if (message.costUsd !== 0) {
      obj.costUsd = message.costUsd;
    }
    if (message.toolCalls !== 0) {
      obj.toolCalls = Math.round(message.toolCalls);
    }
    if (message.filesTouched?.length) {
      obj.filesTouched = message.filesTouched;
    }
    return obj;
  },

  create<I extends Exact<DeepPartial<AgentMetrics>, I>>(base?: I): AgentMetrics {
    return AgentMetrics.fromPartial(base ?? ({} as any));
  },
  fromPartial<I extends Exact<DeepPartial<AgentMetrics>, I>>(object: I): AgentMetrics {
    const message = createBaseAgentMetrics();
    message.inputTokens = object.inputTokens ?? 0;
    message.outputTokens = object.outputTokens ?? 0;
    message.reasoningTokens = object.reasoningTokens ?? 0;
    message.costUsd = object.costUsd ?? 0;
    message.toolCalls = object.toolCalls ?? 0;
    message.filesTouched = object.filesTouched?.map((e) => e) || [];
    return message;
  },
};

